using System;
using System.Collections.Generic;
using Newtonsoft.Json;

namespace Wick.Economy
{
    /// <summary>
    /// The economy as data: prices, upgrade times, star gates, loot numbers, ad caps, products,
    /// the Heist Pass and achievements. Shared by the game (display) and Cloud Code (truth); the
    /// live copy is Remote Config's "economy" setting, with a bundled default as fallback
    /// (generated by tools/economy/make_economy.py). Nothing here is read by the raid sim.
    /// </summary>
    public sealed class EconomyConfig
    {
        /// <summary>Bumped on incompatible changes; a reader ignores configs it can't understand.</summary>
        public const int SupportedVersion = 1;

        public int Version { get; set; }
        public LootConfig Loot { get; set; } = new LootConfig();
        public List<VaultLevelStep> VaultLevels { get; set; } = new List<VaultLevelStep>();
        public List<LanternStep> Lantern { get; set; } = new List<LanternStep>();
        public WorkshopConfig Workshops { get; set; } = new WorkshopConfig();
        public SpeedUpConfig SpeedUp { get; set; } = new SpeedUpConfig();
        public AdsConfig Ads { get; set; } = new AdsConfig();
        public List<Product> Products { get; set; } = new List<Product>();
        public ClubConfig Club { get; set; } = new ClubConfig();
        public PassConfig Pass { get; set; } = new PassConfig();
        public List<Achievement> Achievements { get; set; } = new List<Achievement>();

        public static EconomyConfig Parse(string json)
        {
            EconomyConfig c = JsonConvert.DeserializeObject<EconomyConfig>(json);
            if (c == null || c.Version != SupportedVersion)
            {
                throw new FormatException("Economy config version " + (c?.Version ?? 0) + " isn't supported (expects " + SupportedVersion + ")");
            }

            return c;
        }

        /// <summary>The step that raises the Vault Level to level, or null past the top.</summary>
        public VaultLevelStep VaultLevelTo(int level)
        {
            return VaultLevels.Find(s => s.Level == level);
        }

        public LanternStep LanternTo(int level)
        {
            return Lantern.Find(s => s.Level == level);
        }

        public AdPlacement Placement(string id)
        {
            return Ads.Placements.Find(p => p.Id == id);
        }

        public Product Product(string id)
        {
            return Products.Find(p => p.Id == id);
        }

        public Achievement Achievement(string id)
        {
            return Achievements.Find(a => a.Id == id);
        }
    }

    /// <summary>What StartUpgrade and FinishUpgrade can build.</summary>
    public static class UpgradeKinds
    {
        public const string VaultLevel = "vaultLevel";
        public const string Lantern = "lantern";
    }

    public sealed class LootConfig
    {
        /// <summary>Most gold one raid pays, per defender Vault Level.</summary>
        public int CapPerLevel { get; set; }

        /// <summary>Gold to the defender when a raid on their vault fails, per Vault Level.</summary>
        public int DefenceBonusPerLevel { get; set; }

        /// <summary>A robbed defender loses at most this share of their gold.</summary>
        public int MaxLossPercent { get; set; }

        /// <summary>Gold for a failed verified raid, per defender Vault Level, so a bad run never feels wasted.</summary>
        public int ConsolationPerLevel { get; set; }

        public int WaxPerStar { get; set; }
        public int ShieldMinutes { get; set; }
    }

    /// <summary>Raising the Vault Level to Level: gold, build time and lifetime raid stars (the star gate).</summary>
    public sealed class VaultLevelStep
    {
        public int Level { get; set; }
        public long Gold { get; set; }
        public int Minutes { get; set; }
        public int Stars { get; set; }
    }

    /// <summary>
    /// The Lantern, Wick's light: each level costs wax and needs a Vault Level, so at any Vault
    /// Level everyone can reach the same light. Its raid effect arrives with the balance pass (M10).
    /// </summary>
    public sealed class LanternStep
    {
        public int Level { get; set; }
        public long Wax { get; set; }
        public int Minutes { get; set; }
        public int MinVaultLevel { get; set; }

        /// <summary>Light radius added, in sub-tile units (1 tile = 1000).</summary>
        public int LightBonus { get; set; }
    }

    public sealed class WorkshopConfig
    {
        public int Base { get; set; } = 1;
        public int Max { get; set; } = 3;
    }

    public sealed class SpeedUpConfig
    {
        public int GemsPerHour { get; set; }
        public int MinGems { get; set; }

        /// <summary>Gems to finish an upgrade with this much time left (rounded up, at least MinGems).</summary>
        public long GemsFor(long remainingMs)
        {
            if (remainingMs <= 0)
            {
                return 0;
            }

            long gems = (remainingMs * GemsPerHour + 3_600_000 - 1) / 3_600_000;
            return Math.Max(MinGems, gems);
        }
    }

    public sealed class AdsConfig
    {
        public int DailyTotal { get; set; }
        public List<AdPlacement> Placements { get; set; } = new List<AdPlacement>();
    }

    public sealed class AdPlacement
    {
        public string Id { get; set; }
        public int Daily { get; set; }

        /// <summary>upgrade_speedup: minutes taken off one upgrade.</summary>
        public int Minutes { get; set; }

        /// <summary>raid_double_loot: how soon after the raid it can be claimed.</summary>
        public int WindowMinutes { get; set; }

        /// <summary>shop_chest: what the chest holds.</summary>
        public Grant Grant { get; set; }
    }

    public sealed class Product
    {
        public string Id { get; set; }

        /// <summary>"consumable", "nonConsumable" or "subscription".</summary>
        public string Kind { get; set; }

        /// <summary>Indicative GBP price for display before the store's localised price loads.</summary>
        public string Price { get; set; }

        public Grant Grant { get; set; } = new Grant();
    }

    public sealed class ClubConfig
    {
        public int DailyGems { get; set; }
        public int Workshops { get; set; }
        public List<string> Cosmetics { get; set; } = new List<string>();
    }

    public sealed class PassConfig
    {
        public string Season { get; set; }
        public DateTime StartsUtc { get; set; }
        public DateTime EndsUtc { get; set; }
        public int Tiers { get; set; }
        public int XpPerTier { get; set; }
        public PassXp Xp { get; set; } = new PassXp();
        public List<PassReward> Rewards { get; set; } = new List<PassReward>();

        /// <summary>Tiers reached with this much XP (0 to Tiers).</summary>
        public int TierFor(long xp)
        {
            return XpPerTier <= 0 ? 0 : (int)Math.Min(Tiers, xp / XpPerTier);
        }

        public PassReward Reward(int tier)
        {
            return Rewards.Find(r => r.Tier == tier);
        }
    }

    public sealed class PassXp
    {
        public int Raid { get; set; }
        public int ThreeStarBonus { get; set; }
        public int Defence { get; set; }
        public int DailyFirstWin { get; set; }
    }

    public sealed class PassReward
    {
        public int Tier { get; set; }
        public Grant Free { get; set; } = new Grant();
        public Grant Premium { get; set; } = new Grant();
    }

    /// <summary>A long-term goal with bronze, silver and gold thresholds on one server-tracked stat.</summary>
    public sealed class Achievement
    {
        public string Id { get; set; }

        /// <summary>"snuffs", "perfectEscapes", "raids", "vaultLevel" or "linkOpens".</summary>
        public string Stat { get; set; }

        public string Title { get; set; }
        public List<long> Tiers { get; set; } = new List<long>();
        public List<Grant> Grants { get; set; } = new List<Grant>();
    }

    /// <summary>
    /// Everything the economy can hand out. Deliberately only currencies, cosmetics, workshop slots,
    /// pass and club access: none of it is read by RaidSim. Adding a field here means re-checking
    /// fairness (FairnessTests guard the list).
    /// </summary>
    public sealed class Grant
    {
        public long Gold { get; set; }
        public long Wax { get; set; }
        public long Gems { get; set; }
        public int Workshops { get; set; }
        public List<string> Cosmetics { get; set; } = new List<string>();

        /// <summary>Season id whose premium row this unlocks.</summary>
        public string PassPremium { get; set; }

        /// <summary>Wick Club membership.</summary>
        public bool Club { get; set; }

        [JsonIgnore]
        public bool IsEmpty =>
            Gold == 0 && Wax == 0 && Gems == 0 && Workshops == 0 && (Cosmetics == null || Cosmetics.Count == 0) &&
            string.IsNullOrEmpty(PassPremium) && !Club;
    }
}
